package io.github.ningpp.compat;

import java.nio.charset.StandardCharsets;

/**
 * Replacement for System.Buffers.Text.Utf8Formatter (generated by CSharpToJava converter).
 * Formats values into a UTF-8 byte span (represented as Integer[] holding byte values).
 */
public final class Utf8Formatter {
    private Utf8Formatter() {
    }

    private static boolean writeBytes(byte[] bytes, Span<Integer> destination, IntHolder bytesWritten) {
        if (bytes.length > destination.length()) {
            bytesWritten.value = 0;
            return false;
        }
        for (int i = 0; i < bytes.length; i++) {
            destination.set(i, bytes[i] & 0xFF);
        }
        bytesWritten.value = bytes.length;
        return true;
    }

    /** Mirrors Utf8Formatter.TryFormat(int, Span&lt;byte&gt;, out int). */
    public static boolean tryFormat(int value, Span<Integer> destination, IntHolder bytesWritten) {
        return writeBytes(Integer.toString(value).getBytes(StandardCharsets.US_ASCII), destination, bytesWritten);
    }

    /** Mirrors Utf8Formatter.TryFormat(int, Span&lt;byte&gt;, out int, StandardFormat). */
    public static boolean tryFormat(int value, Span<Integer> destination, IntHolder bytesWritten, StandardFormat format) {
        char symbol = format.getSymbol();
        String text;
        if (symbol == 'X' || symbol == 'x') {
            int precision = format.getPrecision() & 0xFF;
            String hex = Integer.toHexString(value);
            if (precision != 0xFF && precision > hex.length()) {
                hex = String.format("%0" + precision + "d", 0).replace('0', '0') + hex;
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < precision - hex.length() + (precision > hex.length() ? 0 : 0); i++) sb.append('0');
                sb.append(hex);
                text = sb.toString();
            } else {
                text = hex;
            }
            if (symbol == 'X') text = text.toUpperCase();
        } else if (symbol == 'D' || symbol == 'd') {
            int precision = format.getPrecision() & 0xFF;
            String digits = Integer.toString(value);
            if (precision != 0xFF && precision > digits.length()) {
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < precision - digits.length(); i++) sb.append('0');
                sb.append(digits);
                text = sb.toString();
            } else {
                text = digits;
            }
        } else {
            text = Integer.toString(value);
        }
        return writeBytes(text.getBytes(StandardCharsets.US_ASCII), destination, bytesWritten);
    }

    /** Mirrors Utf8Formatter.TryFormat(long, Span&lt;byte&gt;, out int). */
    public static boolean tryFormat(long value, Span<Integer> destination, IntHolder bytesWritten) {
        return writeBytes(Long.toString(value).getBytes(StandardCharsets.US_ASCII), destination, bytesWritten);
    }

    /** Mirrors Utf8Formatter.TryFormat(double, Span&lt;byte&gt;, out int). */
    public static boolean tryFormat(double value, Span<Integer> destination, IntHolder bytesWritten) {
        return writeBytes(Double.toString(value).getBytes(StandardCharsets.US_ASCII), destination, bytesWritten);
    }

    /** Mirrors Utf8Formatter.TryFormat(float, Span&lt;byte&gt;, out int). */
    public static boolean tryFormat(float value, Span<Integer> destination, IntHolder bytesWritten) {
        return writeBytes(Float.toString(value).getBytes(StandardCharsets.US_ASCII), destination, bytesWritten);
    }

    /** Mirrors Utf8Formatter.TryFormat(bool, Span&lt;byte&gt;, out int). */
    public static boolean tryFormat(boolean value, Span<Integer> destination, IntHolder bytesWritten) {
        return writeBytes(Boolean.toString(value).getBytes(StandardCharsets.US_ASCII), destination, bytesWritten);
    }

    /** Mirrors Utf8Formatter.TryFormat(Decimal, Span&lt;byte&gt;, out int). */
    public static boolean tryFormat(Decimal value, Span<Integer> destination, IntHolder bytesWritten) {
        return writeBytes(value.toString().getBytes(StandardCharsets.US_ASCII), destination, bytesWritten);
    }

    /** Mirrors Utf8Formatter.TryFormat(UUID, Span&lt;byte&gt;, out int). */
    public static boolean tryFormat(UUID value, Span<Integer> destination, IntHolder bytesWritten) {
        return writeBytes(value.toString().getBytes(StandardCharsets.US_ASCII), destination, bytesWritten);
    }

    /** Mirrors Utf8Formatter.TryFormat(DateTime, Span&lt;byte&gt;, out int, StandardFormat). */
    public static boolean tryFormat(CSharpDateTime value, Span<Integer> destination, IntHolder bytesWritten, StandardFormat format) {
        return writeBytes(value.toString().getBytes(StandardCharsets.US_ASCII), destination, bytesWritten);
    }

    /** Mirrors Utf8Formatter.TryFormat(DateTimeOffset, Span&lt;byte&gt;, out int, StandardFormat). */
    public static boolean tryFormat(CSharpDateTimeOffset value, Span<Integer> destination, IntHolder bytesWritten, StandardFormat format) {
        return writeBytes(value.toString().getBytes(StandardCharsets.US_ASCII), destination, bytesWritten);
    }
}
